<!-- 本人反馈与受限运维入口；前端显示控制不构成权限，所有维护请求由后端再次判定。 -->
<script setup lang="ts">
import {ref} from "vue";
import {feedbackLabel,problemStateLabel} from "../workspace/support";
import {Api} from "../workspace/client";
/** 固定反馈摘要，不包含会话正文。 */
type Feedback={id:string;problem:string;state:string;category:string};
/** 问题组仅包含错误指纹和维护依据。 */
type Group={id:string;code:string;component:string;state:string;revision:number;count:number;cause:string;repair:string;version:string;regression:string};
/** 原始问题用于定位精确步骤，无提示词或原始异常。 */
type ProblemEvent={id:string;trace:string|null;span:string|null};
const api=new Api(),own=ref<Feedback[]>([]),groups=ref<Group[]>([]),events=ref<ProblemEvent[]>([]),maintenance=ref(false),sensitive=ref(false),notice=ref(""),detail=ref(""),trace=ref(""),selected=ref<Group|null>(null),query=ref(""),next=ref("TRIAGED"),cause=ref("UNKNOWN"),repair=ref("CODE"),version=ref(""),regression=ref(""),passed=ref(false),duplicate=ref(""),busy=ref(false);
/** 主动展开后才读私有摘要，默认不会请求敏感正文。 */
async function refresh():Promise<void>{notice.value="";try{own.value=await api.get<Feedback[]>("/api/v1/support/feedback");const access=await api.get<{maintenance:boolean;sensitive:boolean}>("/api/v1/support/access");maintenance.value=access.maintenance;sensitive.value=access.sensitive;if(maintenance.value)groups.value=await api.get<Group[]>("/api/v1/support/maintenance/groups");}catch{notice.value="问题记录暂时无法读取。";}}
/** @param id 精确反馈 @param admin 额外敏感授权读取，服务器留审计。 */
async function read(id:string,admin=false):Promise<void>{detail.value="";try{const r=await api.get<{description:string}>(`/api/v1/support/${admin?"maintenance/":""}feedback/${id}`);detail.value=r.description||"未填写说明。";}catch{notice.value="反馈不可见或读取未获授权。";}}
/** @param id 用户问题或聚合编号，不能凭前端字段获得维护权限。 */
async function inspect(id:string):Promise<void>{selected.value=null;events.value=[];trace.value="";try{selected.value=await api.get<Group>(`/api/v1/support/maintenance/groups/${id}`);events.value=await api.get<ProblemEvent[]>(`/api/v1/support/maintenance/groups/${id}/events`);}catch{notice.value="问题不可见、编号无效或权限已撤销。";}}
/** @param id 实际链路，固定步骤视图上限200；读取会留审计。 */
async function inspectTrace(id:string):Promise<void>{try{const r=await api.get<unknown>(`/api/v1/support/maintenance/traces/${id}`);trace.value=JSON.stringify(r,null,2);}catch{notice.value="链路读取失败或无权限。";}}
/** 维护状态须显式提交；修复及验证仍由后端状态机和CAS判定。 */
async function update():Promise<void>{if(!selected.value||busy.value)return;busy.value=true;try{await api.post(`/api/v1/support/maintenance/groups/${selected.value.id}`,{revision:selected.value.revision,next:next.value,cause:cause.value,repair:repair.value,version:version.value,regression:regression.value,passed:passed.value,duplicateOf:duplicate.value||null});await inspect(selected.value.id);notice.value="状态已更新。";}catch{notice.value="未确认修改。请核对状态顺序、修复版本和回归用例，再刷新检查。";}finally{busy.value=false;}}
/** 展开时读取，关闭清空敏感展示。 */
function toggle(event:Event):void{if((event.target as HTMLDetailsElement).open)void refresh();else{detail.value="";trace.value="";selected.value=null;events.value=[];}}
</script>
<template><details class="support-panel" @toggle="toggle"><summary>反馈与问题记录</summary><button @click="refresh">刷新</button><p role="status">{{notice}}</p><p v-if="!own.length">暂无本人反馈。</p><ul><li v-for="f in own" :key="f.id"><button @click="read(f.id)">{{feedbackLabel(f.category)}} · {{problemStateLabel(f.state)}}</button><small>问题编号 {{f.problem}}</small></li></ul><p v-if="detail" class="private-detail">{{detail}}</p><section v-if="maintenance"><h3>维护查询</h3><p>仅固定诊断元数据。相同错误按小时聚合，不代表根因相同；仅展示最近20组、每组最多100个事件。</p><input v-model="query" aria-label="问题或聚合编号" placeholder="粘贴问题或聚合编号"/><button @click="inspect(query)">定位</button><ul><li v-for="g in groups" :key="g.id"><button @click="inspect(g.id)">{{g.component}} / {{g.code}} · {{g.count}}次 · {{g.state}}</button></li></ul><template v-if="selected"><p>当前状态 {{selected.state}} · 版本 {{selected.revision}}</p><ul><li v-for="e in events" :key="e.id"><small>{{e.id}} · 步骤 {{e.span||'未产生步骤'}}</small><button v-if="e.trace" @click="inspectTrace(e.trace)">查看链路</button></li></ul><select v-model="next" aria-label="下一状态"><option v-for="s in ['TRIAGED','IN_PROGRESS','RESOLVED','VERIFIED','REOPENED','DUPLICATE']" :key="s">{{s}}</option></select><select v-model="cause" aria-label="根因"><option v-for="s in ['UNKNOWN','CODE','CONFIG','PROVIDER','INPUT','CONTEXT','DATA','USER']" :key="s">{{s}}</option></select><select v-model="repair" aria-label="修复类别"><option v-for="s in ['CODE','CONFIG','PROVIDER','CLARIFICATION']" :key="s">{{s}}</option></select><input v-model="version" maxlength="120" placeholder="修复版本" aria-label="修复版本"/><input v-model="regression" maxlength="120" placeholder="回归用例编号" aria-label="回归用例编号"/><input v-model="duplicate" placeholder="重复目标组ID（仅DUPLICATE）" aria-label="重复目标"/><label><input v-model="passed" type="checkbox"/>已实际验证回归通过</label><button :disabled="busy" @click="update">提交状态变更</button></template><details v-if="sensitive"><summary>显式读取反馈正文（留审计）</summary><input v-model="query" aria-label="反馈编号" placeholder="反馈编号，不是问题编号"/><button @click="read(query,true)">读取所选反馈</button></details><pre v-if="trace">{{trace}}</pre></section></details></template>
<style scoped>.support-panel{font-size:12px;padding:10px 14px;overflow-wrap:anywhere;max-width:850px;max-height:240px;overflow:auto;margin:0 auto 12px;border:1px solid #e5e7eb;border-radius:14px;background:#fff}.support-panel small{display:block;color:#64748b}.support-panel button{margin:4px}.support-panel input,.support-panel select{max-width:100%;margin:4px}.private-detail,pre{white-space:pre-wrap;overflow:auto;max-height:350px}</style>
